def digest(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()
def inspect(item,path):
    with Image.open(path) as im:
        im.load()
        assert im.width==im.height and im.mode=="RGBA",item["name"]
        alpha=im.getchannel("A")
        assert alpha.getextrema()==(0,255),item["name"]
        bounds={str(t):alpha.point(lambda a:255 if a>=t else 0).getbbox() for t in [8,64,128]}
        return {"id":item["id"],"name":item["name"],"file":(DEST/(item["name"]+".png")).relative_to(ROOT).as_posix(),"source":item["source"],"width":im.width,"height":im.height,"mode":im.mode,"alpha_extrema":alpha.getextrema(),"visible_bounds":bounds,"sha256":digest(path),"bytes":path.stat().st_size}
current=[inspect(x,Path(x["source"])) for x in ITEMS]
if "--inspect" in sys.argv:
    print(json.dumps(current,ensure_ascii=True))
    raise SystemExit(0)
for item in current:
    b=item["visible_bounds"]["128"]
    assert 0<b[0]<b[2]<item["width"] and 0<b[1]<b[3]<item["height"],"Visible form touches canvas: "+item["name"]
if "--publish" in sys.argv:
    assert ARCHIVE.resolve().is_relative_to((ROOT/"99_보관소").resolve())
    ARCHIVE.mkdir(parents=True,exist_ok=True)
    oldbody=RECORD.read_text(encoding="utf-8")
    olddata=json.loads(re.search(r"# 5 기계 대조 데이터\s*\x60\x60\x60json\n(.*?)\n\x60\x60\x60",oldbody,re.S).group(1))
    assert len(olddata["images"])==9
    old_inventory=[]
    for old in olddata["images"]:
        source=(ROOT/old["file"]).resolve()
        assert source.is_relative_to(DEST.resolve()) and digest(source)==old["sha256"],"Current image changed: "+old["name"]
        backup=ARCHIVE/source.name
        if backup.exists():
            assert digest(backup)==old["sha256"],"Archive differs: "+str(backup)
        else:
            shutil.copyfile(source,backup)
        assert digest(backup)==old["sha256"]
        old_inventory.append({"name":old["name"],"archive_path":backup.relative_to(ROOT).as_posix(),"sha256":old["sha256"]})
    previous=ARCHIVE/RECORD.name
    if previous.exists():
        assert previous.read_bytes()==RECORD.read_bytes(),"Archive record differs"
    else:
        shutil.copyfile(RECORD,previous)
    note='---\ntitle: "덜미 소품 실사 초안 보관 안내"\ntype: system\ncreated: "2026-10-21"\nupdated: "2026-10-21"\n---\n\n# 1 보관 이유\n\n- 사용자가 실사에 가까운 외형을 지적하고 투박한 목재와 종이 재질로 다시 생성하도록 요청하여 기존 PNG 9개와 당시 작업 기록을 비교용으로 보존함.\n- 대체 파일과 현재 기록 위치: '+DEST.relative_to(ROOT).as_posix()+'임.\n- 이 폴더의 작업 기록은 이전 시점의 스냅숏이며 당시 자산 경로와 검수 결과를 현재안으로 해석하지 않음.\n'
    (ARCHIVE/"보관 안내.md").write_text(note,encoding="utf-8")
    for item in ITEMS:
        target=DEST/(item["name"]+".png")
        shutil.copyfile(item["source"],target)
        assert digest(target)==digest(Path(item["source"]))
    old_inventory_json=json.dumps(old_inventory,ensure_ascii=False,indent=2)
    lines=['---','title: "덜미 소품 이미지 작업 기록"','type: asset','created: "2026-10-21"','updated: "2026-10-21"','status: review','sources:','  - "[[04_상세 기획/덜미 - 나만의 꼭두각시/덜미 - 나만의 꼭두각시 기획서]]"','asset_files:']
    lines += ['  - "'+x["file"]+'"' for x in current]
    lines += ['---','','# 1 용도와 입력 범위','','- 사용자 요청: 소품 9개를 독립적인 1:1 투명 PNG로 사용하고, 실사에 가까운 기존 결과를 투박한 목재와 종이 재질로 다시 생성함.','- 입력: [덜미 - 나만의 꼭두각시 기획서: 꼭두각시 체험 진행](<../../../../../04_상세 기획/덜미 - 나만의 꼭두각시/덜미 - 나만의 꼭두각시 기획서.md#7-꼭두각시-체험-진행>)의 소품 항목과 사용자의 재질 수정 지시임. 기획서 본문과 승인 상태는 변경하지 않음.','- 부적가리: 사용자가 설명한 화로의 불을 젓는 긴 부지깽이 막대로 표현함.','- 스타일 참조: 먼저 수정한 찬물 그릇의 거친 조각면, 종이 덧붙임, 무광 물감과 굵은 붓 자국을 나머지 8개에 함께 입력함. 소품의 종류와 큰 외곽은 각 기존 이미지에서 참조함.','','# 2 재질 수정 기준','','| 대상 | 적용한 외형 |','|---|---|','| 찬물 그릇 | 투박한 목재 그릇, 물을 나타내는 푸른 종이판과 흰 붓 물결 |','| 노리개 | 목재 매듭과 장식, 넓은 종이 술 |','| 반다지, 함롱 | 거친 판재와 칠한 부속, 자개를 나타내는 종이 꽃과 잎 |','| 깨진 매운독, 땅문서 | 겹친 한지와 종이 단면, 단순한 그림과 균열 |','| 엽전 꾸러미, 부적가리 | 칠한 목재 원판과 종이 끈, 각진 목재 막대와 검은 그을음 표현 |','','# 3 현재 파일과 검수','','| 파일 | 픽셀 | 모드 | SHA-256 |','|---|---|---|---|']
    for x in current:
        lines.append('| ['+x["name"]+'.png](<'+x["name"]+'.png>) | '+str(x["width"])+' × '+str(x["height"])+' | RGBA | '+x["sha256"]+' |')
    lines += ['','- 직접 시각 검수: 9개 모두 거친 목재와 종이의 조형, 무광 채색, 단일 소품과 전체 형태를 확인함. 실제 금속, 비단과 옥의 광택 및 투명 물 표현을 제거하는 방향으로 수정함.','- 파일 검수: PNG 9개 전체 디코딩, 1:1, RGBA와 알파 0~255, 생성 출력과 반영본 해시 일치 확인함. 알파 128 이상 형태는 화면 경계 안에 있음.','- 생성 출력의 알파를 보존함. 매우 약한 반투명 픽셀과 정밀 배경 합성은 별도 확인 범위이며 파일 재단이나 이미지 후처리는 수행하지 않음.','- 땅문서의 그림과 인장, 엽전 무늬는 게임 리소스의 가상 표현임. 실제 유물의 문자나 양식 고증은 수행하지 않음.','- 정보그래픽이 아닌 소품 단독 이미지로 별도 설명 라벨은 없으며 블라인드 문자 전사는 수행하지 않음. 게임 엔진 가져오기, 피벗과 충돌체 및 사용자 채택은 미확인임.','','# 4 이전 결과 보존','','- 기존 실사 초안은 사용자 재질 수정 요청으로 현재 사용본에서 제외함. 이전 PNG 9개와 당시 작업 기록을 보존하고 해시 대조함.','- 보관 위치는 '+ARCHIVE.relative_to(ROOT).as_posix()+'임. 보관소 내부로 연결하는 링크는 만들지 않음.','- 이전 작업 기록의 검수는 당시 결과에 대한 기록이며, 이번 재질 수정본의 검수와 구분함.','','# 5 기계 대조 데이터','','```json',json.dumps({"schema":"prop-image-record-v1","tool":"image_gen","requested_count":9,"generated_count":9,"pending":[],"images":current,"archive_inventory":old_inventory},ensure_ascii=False,indent=2),'```','','# 6 실제 생성 프롬프트','','- 생성 경로: 내장 image_gen, 재질 수정 이미지 9회 생성함. 모델 식별자는 반환되지 않아 미확인임.','- 마지막 네 항목의 최초 요청 4건은 참조 경로 검증 오류로 이미지 생성 전에 실패하여 경로를 수정하고 실행함. 실제 이미지 출력은 항목별 한 개씩임.','- 설정: transparent_background: true, referenced_image_paths에 편집 대상과 필요한 스타일 참조를 전달함.']
    for n,x in enumerate(ITEMS,1):
        lines += ['','## 6.'+str(n)+' '+x["name"],'','<!-- image-prompt:'+x["id"]+' -->','```text',x["prompt"],'```','','- 입력 경로: '+', '.join('`'+p+'`' for p in x["reference_paths"])+'.','- 생성 출력: `'+x["source"]+'`.']
    RECORD.write_text('\n'.join(lines)+'\n',encoding="utf-8")
body=RECORD.read_text(encoding="utf-8")
data=json.loads(re.search(r"# 5 기계 대조 데이터\s*\x60\x60\x60json\n(.*?)\n\x60\x60\x60",body,re.S).group(1))
assert len(data["images"])==9 and data["generated_count"]==9
assert {x["id"] for x in current}==set(re.findall(r"<!-- image-prompt:([a-z0-9-]+) -->",body))
for x in current:
    target=ROOT/x["file"]
    assert digest(target)==x["sha256"]
    recorded=next(y for y in data["images"] if y["id"]==x["id"])
    assert recorded["sha256"]==x["sha256"]
for old in data["archive_inventory"]:
    assert digest(ROOT/old["archive_path"])==old["sha256"]
for ref in re.findall(r"\[[^\]\n]*\]\(<([^>]+)>\)",body):
    target=(RECORD.parent/ref.split("#",1)[0]).resolve()
    assert target.is_file() and target.is_relative_to(ROOT) and not target.is_relative_to(ROOT/"99_보관소"),str(target)
print(json.dumps({"passed":True,"images":9,"square_rgba":True,"archive_images":9,"prompts":9},ensure_ascii=True))

